from utils.extraction import head_bytes
AI = ["midjourney", "dall-e", "dalle", "stable diffusion", "stablediffusion", "firefly", "openai", "sora", "runway",
      "pika", "elevenlabs", "synthesia", "heygen", "deepfake", "comfyui", "automatic1111", "generated by ai"]
CAM = ["canon", "nikon", "apple", "samsung", "sony", "google", "fujifilm", "xiaomi", "huawei", "olympus", "panasonic", "gopro"]

def analyze(path, kind):
    low = head_bytes(path).lower()
    return {"ai_tags": [k for k in AI if k.encode() in low],
            "exif": b"exif" in low,
            "camera": any(c.encode() in low for c in CAM),
            "content_credentials": b"c2pa" in low or b"jumb" in low}
